/* Actual learned levels and current installed Source skill/talent values. */
#include "progression.h"
#include "items.h"
#include "extra_heroes.h"
#include "roster_heroes.h"
typedef struct {const char *field;int value[4],hero_step100;unsigned short effect_first;unsigned char effect_count,count;} DotaProgressionValue;
typedef struct {unsigned char talent,op;int value100;} DotaProgressionValueEffect;
#include "progression_data.h"
static int min_i(int a,int b){return a<b?a:b;}
static int max_i(int a,int b){return a>b?a:b;}
static int valid(const DotaGame *g,int h){return g&&(unsigned)h<DOTA_HERO_COUNT&&g->units[h].active&&g->units[h].type==DOTA_HERO&&(unsigned)g->units[h].hero_id<DOTA_HERO_TYPES;}
static int unit(const DotaUnit *u){return u&&u->type==DOTA_HERO&&(unsigned)u->hero_id<DOTA_HERO_TYPES;}
static inline int live(const DotaGame *g,int h){return g&&(unsigned)h<DOTA_MAX_UNITS&&g->units[h].active&&g->units[h].hp>0;}
static int compare(const char *a,const char *b){while(*a&&*a==*b){++a;++b;}return (unsigned char)*a-(unsigned char)*b;}
static int bit_count(unsigned x){int n=0;while(x){x&=x-1u;++n;}return n;}
static DotaProgressionHero *touch(DotaGame *g,int h);
const DotaProgressionBase *dota_progression_base(int h){return (unsigned)h<DOTA_HERO_TYPES?&progression_bases[h]:0;}
int dota_progression_primary(int h){const DotaProgressionBase *b=dota_progression_base(h);return b?b->primary:0;}
void dota_progression_base_attributes100(const DotaUnit *u,int *s,int *a,int *i){const DotaProgressionBase *b=u?dota_progression_base(u->hero_id):0;int level=u?max_i(0,u->level-1):0;if(s)*s=b?b->str100+b->str_gain100*level:0;if(a)*a=b?b->agi100+b->agi_gain100*level:0;if(i)*i=b?b->int100+b->int_gain100*level:0;}
int dota_progression_rank(const DotaUnit *u,int skill){return unit(u)&&(unsigned)skill<4u?min_i(u->learned[skill],progression_skill_max[u->hero_id][skill]):0;}
int dota_progression_skill_max(int h,int skill){return (unsigned)h<DOTA_HERO_TYPES&&(unsigned)skill<4u?progression_skill_max[h][skill]:0;}
int dota_progression_skill_required(const DotaUnit *u,int skill){return unit(u)&&(unsigned)skill<4u?progression_skill_required[u->hero_id][skill]+dota_progression_rank(u,skill)*progression_skill_gap[u->hero_id][skill]:0;}
int dota_progression_points(const DotaGame *g,int h){const DotaUnit *u;int spent,i;if(!valid(g,h))return 0;u=&g->units[h];spent=u->attribute_bonus_rank;for(i=0;i<4;++i)spent+=u->learned[i];return max_i(0,min_i(22,u->level)-spent);}
int dota_progression_talent_points(const DotaGame *g,int h){static const unsigned char at[8]={10,15,20,25,27,28,29,30};int i,earned=0;if(!valid(g,h))return 0;for(i=0;i<8;++i)if(g->units[h].level>=at[i])++earned;return max_i(0,earned-bit_count(g->units[h].talents&255u));}
int dota_progression_can_learn(const DotaGame *g,int h,int skill){return valid(g,h)&&(unsigned)skill<4u&&g->state==DOTA_PLAYING&&dota_progression_points(g,h)>0&&dota_progression_rank(&g->units[h],skill)<dota_progression_skill_max(g->units[h].hero_id,skill)&&g->units[h].level>=dota_progression_skill_required(&g->units[h],skill);}
int dota_progression_learn(DotaGame *g,int h,int skill){if(!dota_progression_can_learn(g,h,skill))return 0;++g->units[h].learned[skill];dota_rules_item_recalc(g,h);dota_progression_level_changed(g,h);return 1;}
int dota_progression_talent_level(int row){return (unsigned)row<4u?10+row*5:0;}
int dota_progression_has_talent(const DotaUnit *u,int index){return unit(u)&&(unsigned)index<8u&&(u->talents&(1u<<index))!=0;}
int dota_progression_can_talent(const DotaGame *g,int h,int index){const DotaUnit *u;if(!valid(g,h)||(unsigned)index>=8u||g->state!=DOTA_PLAYING||dota_progression_talent_points(g,h)<=0)return 0;u=&g->units[h];return !dota_progression_has_talent(u,index)&&u->level>=dota_progression_talent_level(index/2)&&(!(u->talents&(3u<<((index/2)*2)))||u->level>=27+index/2);}
int dota_progression_learn_talent(DotaGame *g,int h,int index){if(!dota_progression_can_talent(g,h,index))return 0;g->units[h].talents|=(unsigned short)(1u<<index);dota_rules_item_recalc(g,h);return 1;}
const char *dota_progression_talent_name(int h,int index){return (unsigned)h<DOTA_HERO_TYPES&&(unsigned)index<8u?progression_talent_name[h][index]:"";}
const char *dota_progression_talent_description(int h,int index){return (unsigned)h<DOTA_HERO_TYPES&&(unsigned)index<8u?progression_talent_description[h][index]:"";}
int dota_progression_can_attributes(const DotaGame *g,int h){return valid(g,h)&&g->state==DOTA_PLAYING&&dota_progression_points(g,h)>0&&g->units[h].attribute_bonus_rank<DOTA_ATTRIBUTE_MAX&&g->units[h].level>=dota_progression_attribute_required(&g->units[h]);}
int dota_progression_learn_attributes(DotaGame *g,int h){if(!dota_progression_can_attributes(g,h))return 0;++g->units[h].attribute_bonus_rank;dota_rules_item_recalc(g,h);return 1;}
int dota_progression_attribute_bonus(const DotaUnit *u){return unit(u)&&u->attribute_bonus_rank?progression_attribute_value[min_i(u->attribute_bonus_rank,DOTA_ATTRIBUTE_MAX)-1]:0;}
int dota_progression_attribute_max(void){return DOTA_ATTRIBUTE_MAX;}
int dota_progression_attribute_required(const DotaUnit *u){return unit(u)?DOTA_ATTRIBUTE_REQUIRED+u->attribute_bonus_rank*DOTA_ATTRIBUTE_GAP:0;}
int dota_progression_innate_rank(const DotaUnit *u){return unit(u)&&u->level>0?1:0;}
const char *dota_progression_innate_name(int h){return (unsigned)h<DOTA_HERO_TYPES?progression_innate_name[h]:"";}
const char *dota_progression_innate_description(int h){return (unsigned)h<DOTA_HERO_TYPES?progression_innate_description[h]:"";}
void dota_progression_level_changed(DotaGame *g,int h){int skill,any;if(!valid(g,h))return;touch(g,h);while(dota_progression_points(g,h)>0){any=0;for(skill=0;skill<4;++skill)if(dota_progression_can_learn(g,h,skill)){any=1;break;}if(any||!dota_progression_can_attributes(g,h))break;dota_progression_learn_attributes(g,h);}}
void dota_progression_bot(DotaGame *g,int h){int guard=0,k,row,id;if(!valid(g,h)||h==g->player)return;id=g->units[h].hero_id;
 while(dota_progression_talent_points(g,h)>0&&guard++<8){int done=0;for(row=3;row>=0;--row){int choice=row*2+((id+row)&1);if(!dota_progression_can_talent(g,h,choice))choice^=1;if(dota_progression_can_talent(g,h,choice)){dota_progression_learn_talent(g,h,choice);done=1;break;}}if(!done)break;}
 guard=0;while(dota_progression_points(g,h)&&guard++<30){int done=0;if(dota_progression_can_learn(g,h,3)){dota_progression_learn(g,h,3);continue;}for(k=0;k<3;++k){int skill=(k+(id==0||id==2?2:0))%3;if(dota_progression_can_learn(g,h,skill)){dota_progression_learn(g,h,skill);done=1;break;}}if(done)continue;if(dota_progression_can_attributes(g,h)){dota_progression_learn_attributes(g,h);continue;}break;}}
int dota_progression_value100(const DotaUnit *u,int skill,const char *field,int fallback){unsigned lo,hi;int rank,value,i;if(!unit(u)||(unsigned)skill>=6u||!field)return fallback;rank=skill<4?dota_progression_rank(u,skill):1;if(!rank)return 0;lo=progression_value_ranges[u->hero_id][skill];hi=progression_value_ranges[u->hero_id][skill+1];while(lo<hi){unsigned mid=(lo+hi)/2;const DotaProgressionValue *v=&progression_values[mid];int cmp=compare(v->field,field);if(cmp<0)lo=mid+1;else if(cmp>0)hi=mid;else{value=v->value[min_i(rank,v->count)-1]+v->hero_step100*max_i(0,u->level-1);for(i=0;i<v->effect_count;++i){const DotaProgressionValueEffect *e=&progression_value_effects[v->effect_first+i];if(!dota_progression_has_talent(u,e->talent))continue;if(e->op==1)value+=e->value100;else if(e->op==2)value=(int)((long long)value*(10000+e->value100)/10000);else if(e->op==3)value=(int)((long long)value*e->value100/100);else value=e->value100;}return value;}}return fallback;}
int dota_progression_stat_bonus(const DotaUnit *u,int stat){int h,rank,bonus=0;if(!unit(u))return 0;h=u->hero_id;rank=dota_progression_attribute_bonus(u);if(stat>=ITEM_STAT_STRENGTH&&stat<=ITEM_STAT_INTELLECT)bonus=rank*100;if(h==0&&stat==ITEM_STAT_STRENGTH&&dota_progression_has_talent(u,4))bonus+=1500;if(h==1&&stat==ITEM_STAT_DAMAGE&&dota_progression_has_talent(u,0))bonus+=25;if(h==3&&stat==ITEM_STAT_HEALTH&&dota_progression_has_talent(u,0))bonus+=200;if(h==3&&stat==ITEM_STAT_INTELLECT&&dota_progression_has_talent(u,1))bonus+=1200;if(h==5&&stat==ITEM_STAT_AOE_BONUS&&dota_progression_has_talent(u,4))bonus+=75;if(h==6&&stat==ITEM_STAT_ARMOR&&dota_progression_has_talent(u,0))bonus+=500;if(h==6&&stat==ITEM_STAT_SPELL_LIFESTEAL&&dota_progression_has_talent(u,2))bonus+=800;return bonus;}
static DotaProgressionHero *touch(DotaGame *g,int h){DotaProgressionHero *s=&g->progression.hero[h];if(s->generation!=g->units[h].generation){unsigned char *p=(unsigned char*)s;unsigned n=sizeof(*s);while(n--)*p++=0;s->generation=g->units[h].generation;s->blade_next_at=g->tick+max_i(1,dota_progression_value100(&g->units[h],5,"stack_gain_time",200)*DOTA_HZ/100);}return s;}
static int source_range(int x,int y,int xx,int yy,int radius){long long dx=x-xx,dy=y-yy;return (dx*dx+dy*dy)*16<=(long long)radius*radius;}
static void axe_update(DotaGame *g,int h,DotaProgressionHero *s){int i,alone=1,radius=dota_progression_value100(&g->units[h],5,"radius",70000)/100;
    for(i=0;i<DOTA_HERO_COUNT;++i)if(i!=h&&live(g,i)&&g->units[i].team==g->units[h].team&&source_range(g->units[h].x,g->units[h].y,g->units[i].x,g->units[i].y,radius)){alone=0;break;}
    if(alone)s->axe_linger_until=g->tick+dota_progression_value100(&g->units[h],5,"bonus_linger_duration",300)*DOTA_HZ/100;
    s->axe_strength100=!dota_items_broken(g,h)&&(alone||s->axe_linger_until>g->tick)?max_i(0,dota_rules_armor100(g,h))*dota_progression_value100(&g->units[h],5,"armor_pct_as_strength",5000)/10000:0;
}
void dota_progression_stat_delta100(const DotaGame *g,int h,int *str,int *agi,int *intel){const DotaProgressionHero *s;int base_agi;(void)intel;if(!valid(g,h)||dota_items_broken(g,h))return;s=&g->progression.hero[h];if(s->generation!=g->units[h].generation||!live(g,h))return;if(g->units[h].hero_id==DOTA_HERO_AXE&&str)*str+=s->axe_strength100;if(g->units[h].hero_id==DOTA_HERO_JUGGERNAUT&&agi&&s->blade_stacks){dota_progression_base_attributes100(&g->units[h],0,&base_agi,0);*agi+=(int)((long long)base_agi*s->blade_stacks*dota_progression_value100(&g->units[h],5,"agi_bonus_pct_per_stack",250)/10000);}}
void dota_progression_stat_delta(const DotaGame *g,int h,int *str,int *agi,int *intel){int s=0,a=0,i=0;dota_progression_stat_delta100(g,h,&s,&a,&i);if(str)*str+=s/100;if(agi)*agi+=a/100;if(intel)*intel+=i/100;}
int dota_progression_move_percent(const DotaGame *g,int h){const DotaProgressionHero *s;if(!valid(g,h)||g->units[h].hero_id!=DOTA_HERO_JUGGERNAUT||dota_items_broken(g,h))return 0;s=&g->progression.hero[h];return s->generation==g->units[h].generation?s->blade_stacks*dota_progression_value100(&g->units[h],5,"movement_speed_pct_per_stack",100)/100:0;}
int dota_progression_attack_critical(const DotaGame *g,int source,int target){int i,value;if(!valid(g,source)||g->units[source].hero_id!=DOTA_HERO_LINA||!live(g,target)||dota_items_broken(g,source))return 100;value=dota_progression_value100(&g->units[source],5,"target_crit_multiplier",0)/100;if(value<=100)return 100;for(i=0;i<DOTA_PROGRESSION_BURNS;++i){const DotaProgressionBurn *b=&g->progression.burn[i];if(b->remaining>0&&b->source==source&&b->source_generation==g->units[source].generation&&b->target==target&&b->target_generation==g->units[target].generation)return value;}return 100;}
static void slow_burn(DotaGame *g,int source,int target,int raw){int i,duration,pct;if(raw<=0||!valid(g,source)||g->units[source].hero_id!=DOTA_HERO_LINA||!live(g,target)||g->units[source].team==g->units[target].team||dota_items_broken(g,source))return;pct=dota_progression_value100(&g->units[source],5,"burn_damage_pct",6400);duration=dota_progression_value100(&g->units[source],5,"burn_duration",400)*DOTA_HZ/100;if(pct<=0||duration<=0)return;for(i=0;i<DOTA_PROGRESSION_BURNS;++i)if(!g->progression.burn[i].remaining)break;if(i<DOTA_PROGRESSION_BURNS){DotaProgressionBurn *b=&g->progression.burn[i];b->source=(uint16_t)source;b->target=(uint16_t)target;b->source_generation=g->units[source].generation;b->target_generation=g->units[target].generation;b->duration=b->remaining=duration;b->total100=(int)((long long)raw*pct/100);b->fraction=0;}}
int dota_progression_ability_damage(DotaGame *g,int source,int target,int amount,int mode){int old_source,old_target,old_pending,dealt;if(!g)return 0;old_source=g->progression.skill_source;old_target=g->progression.skill_target;old_pending=g->progression.skill_pending;g->progression.skill_source=source;g->progression.skill_target=target;g->progression.skill_pending=valid(g,source)&&g->units[source].hero_id==DOTA_HERO_LINA;dealt=dota_rules_item_damage(g,source,target,amount,mode);g->progression.skill_source=old_source;g->progression.skill_target=old_target;g->progression.skill_pending=old_pending;return dealt;}
void dota_progression_on_damage(DotaGame *g,int source,int target,int raw,int dealt,int mode){DotaProgressionHero *s;if(!g||dealt<=0)return;if(g->progression.skill_pending&&g->progression.skill_source==source&&g->progression.skill_target==target&&!g->progression.recursion&&mode!=9){g->progression.skill_pending=0;slow_burn(g,source,target,raw);}if(!valid(g,target))return;s=touch(g,target);if(g->units[target].hero_id==DOTA_HERO_JUGGERNAUT){if(s->blade_stacks&&!s->blade_linger_until)s->blade_linger_until=g->tick+dota_progression_value100(&g->units[target],5,"linger_duration",200)*DOTA_HZ/100;s->blade_next_at=g->tick+max_i(1,dota_progression_value100(&g->units[target],5,"stack_gain_time",200)*DOTA_HZ/100);}}
void dota_progression_on_cast(DotaGame *g,int h,int mana_spent){DotaProgressionHero *s;int i,amount;if(!valid(g,h))return;s=touch(g,h);if(g->units[h].hero_id==DOTA_HERO_AXE){axe_update(g,h,s);return;}if(g->units[h].hero_id!=DOTA_HERO_CRYSTAL_MAIDEN||mana_spent<=0||dota_items_broken(g,h))return;amount=(int)((long long)mana_spent*dota_progression_value100(&g->units[h],5,"mana_multiplier",3000)/10000);if(amount<=0)return;for(i=0;i<DOTA_PROGRESSION_SHIELDS;++i)if(g->progression.shield[i].amount<=0||g->progression.shield[i].until<=g->tick)break;if(i<DOTA_PROGRESSION_SHIELDS){DotaProgressionShield *v=&g->progression.shield[i];v->hero=(uint16_t)h;v->generation=g->units[h].generation;v->until=g->tick+dota_progression_value100(&g->units[h],5,"barrier_duration",800)*DOTA_HZ/100;v->amount=amount;s->glacial_barrier+=amount;s->glacial_until=max_i(s->glacial_until,v->until);}}
int dota_progression_before_damage(DotaGame *g,int source,int target,int amount,int mode){int i;(void)source;if(!g||amount<=0||mode!=0||!valid(g,target))return amount;for(i=0;i<DOTA_PROGRESSION_SHIELDS&&amount>0;++i){DotaProgressionShield *s=&g->progression.shield[i];if(s->hero==target&&s->generation==g->units[target].generation&&s->until>g->tick&&s->amount>0){int blocked=min_i(amount,s->amount);s->amount-=blocked;amount-=blocked;g->progression.hero[target].glacial_barrier=max_i(0,g->progression.hero[target].glacial_barrier-blocked);}}return amount;}
void dota_progression_tick(DotaGame *g){int h,i;if(!g||g->progression.last_tick==g->tick)return;g->progression.last_tick=g->tick;
    for(h=0;h<DOTA_HERO_COUNT;++h)if(valid(g,h)){DotaProgressionHero *s=touch(g,h);DotaUnit *u=&g->units[h];s->glacial_barrier=0;s->glacial_until=0;if(!live(g,h)){s->axe_strength100=s->blade_stacks=s->blade_linger_until=0;continue;}if(u->hero_id==DOTA_HERO_AXE)axe_update(g,h,s);if(u->hero_id==DOTA_HERO_JUGGERNAUT){if(s->blade_linger_until&&s->blade_linger_until<=g->tick){s->blade_stacks=0;s->blade_linger_until=0;}if(!dota_items_broken(g,h)&&g->tick>=s->blade_next_at&&!s->blade_linger_until){s->blade_stacks=min_i(s->blade_stacks+1,dota_progression_value100(u,5,"max_stacks",1000)/100);s->blade_next_at=g->tick+max_i(1,dota_progression_value100(u,5,"stack_gain_time",200)*DOTA_HZ/100);}}}
    for(i=0;i<DOTA_PROGRESSION_SHIELDS;++i){DotaProgressionShield *s=&g->progression.shield[i];if(s->amount<=0)continue;if(!valid(g,s->hero)||!live(g,s->hero)||s->generation!=g->units[s->hero].generation||s->until<=g->tick){s->amount=0;continue;}g->progression.hero[s->hero].glacial_barrier+=s->amount;g->progression.hero[s->hero].glacial_until=max_i(g->progression.hero[s->hero].glacial_until,s->until);}
    for(i=0;i<DOTA_PROGRESSION_BURNS;++i){DotaProgressionBurn *b=&g->progression.burn[i];int elapsed,paid,damage;if(b->remaining<=0)continue;if(!live(g,b->target)||g->units[b->target].generation!=b->target_generation||(unsigned)b->source>=DOTA_MAX_UNITS||g->units[b->source].generation!=b->source_generation){b->remaining=0;continue;}--b->remaining;elapsed=b->duration-b->remaining;if(elapsed%DOTA_HZ&&b->remaining)continue;paid=(int)((long long)b->total100*elapsed/(b->duration*100));damage=paid-b->fraction;b->fraction=paid;if(damage>0){g->progression.recursion++;dota_rules_item_damage(g,b->source,b->target,damage,9);g->progression.recursion--;}}
}
